INSERT OR REPLACE INTO testimonials (id, nombre, pais, bandera, tour_nombre, rating, comentario, foto, fecha, origen, estado, created_at) VALUES 
('1', 'James W.', 'United Kingdom', '🇬🇧', 'Amazon Expedition', 4, 'An absolutely incredible experience. The guides were deeply knowledgeable and passionate about the rainforest. We saw giant river otters, caimans, and countless macaws. The lodge was rustic but perfectly comfortable. Highly recommend this local agency!', '/media/1786477360363-jordy.jpg', '2026-08-22', 'tripadvisor', 'publicado', '2026-08-22T00:00:00.000Z'),
('2', 'Sarah T.', 'United States', '🇺🇸', 'Wildlife Quest', 5, 'The highlight of our Peru trip! Going deep into the Amazon with indigenous guides made all the difference. We felt completely safe while being totally immersed in nature. The night walks through the jungle were mind-blowing. Thank you for everything!', '/media/1787335803567-10290631_478172738980891_705162467606874687_n.jpg', '2025', 'google', 'publicado', '2026-08-22T00:00:00.000Z'),
('3', 'Matteo C.', 'Italy', '🇮🇹', 'Amazon Adventure', 5, 'If you want to see untouched wilderness, this is the company to book with. No crowded tourist traps, just pure Amazon. The food was surprisingly fantastic, and seeing a jaguar resting on the riverbank is a memory I will cherish forever.', '', '2025', 'tripadvisor', 'publicado', '2026-08-22T00:00:00.000Z'),
('4', 'Elena R.', 'Spain', '🇪🇸', 'Manu Reserved Zone', 5, 'Una experiencia inolvidable. Ver a los guacamayos en la colpa de arcilla y navegar por el río Manu fue mágico. El equipo de Manu Jungle Forever nos cuidó en todo momento con una calidez excepcional.', '', '2025', 'google', 'publicado', '2026-08-22T00:00:00.000Z'),
('5', 'Lucas M.', 'Germany', '🇩🇪', 'Wildlife Photography', 5, 'Top notch guiding and logistics. As a photographer, I needed time and patience to get the right shots, and our guide knew the exact spots for birds and amphibians. 10/10 experience.', '', '2025', 'tripadvisor', 'publicado', '2026-08-22T00:00:00.000Z');
